 function avatarFor(id){const player=id===owner?{minecraftId:state.profile?.id,minecraftName:state.profile?.name}:friends.find(f=>f.id===id)||party?.members.find(m=>m.id===id);const identity=(player?.minecraftId||'').replaceAll('-','');return /^[a-f0-9]{32}$/i.test(identity)?image('https://mc-heads.net/avatar/'+identity):image('https://mc-heads.net/avatar/'+encodeURIComponent(player?.minecraftName||player?.name||'MHF_Steve'));}
