 async function init(){if(preview||!state.networkAccount?.id){if(owner){for(const id of [...peers.keys()])drop(id);worlds.clear();engine?.destroy();scope='';owner='';vault=null;party=null;ready=false;api('partyReset').catch(()=>{});}return false;}const account=state.networkAccount.id,endpoint=state.friendsEndpoint;if(ready&&owner===account&&scope&&vault?.endpoint===endpoint)return true;ready=false;for(const peer of peers.keys())drop(peer);engine?.destroy();scope='';iceData=null;iceLoading=null;iceRetryAt=0;owner=account;activeChat='';initialFriends=true;playing.clear();friends=[];worlds.clear();issues.clear();await SpectraSodium.ready;const local=await api('socialLocal');if(owner!==state.networkAccount?.id||local.account!==account)throw Error('Аккаунт изменился');scope=local.scope;vault=local.value;vault.endpoint=endpoint;vault.pins??={};vault.messages??=[];vault.seen??=[];vault.muted??={};vault.notices??=[];vault.outbox??=[];vault.replay??={};vault.pending??=[];vault.connected=vault.connected!==false;engine=SpectraChatCrypto.create(SpectraSodium,account,vault.seed,vault.counter||0);vault.seed=engine.seed;await save();await call('/social/key',{publicKey:engine.publicKey});ready=true;return true;}
