 async function verify(id){await init();const key=await getKey(id),fingerprint=engine.fingerprint(key),changed=vault.pins[id]&&vault.pins[id]!==key;modal(`${closeButton()}<h2>${changed?'Ключ игрока изменился':'Ключи защищённого чата'}</h2><p>${changed?'Возможна переустановка лаунчера или подмена ключа. Уточните у друга перед подтверждением.':'Ключи получаются автоматически при первом контакте и сохраняются на этом устройстве. Для дополнительной проверки сравните отпечатки с другом.'}</p><label>Мой отпечаток<code class="key-fingerprint" data-no-i18n>${engine.fingerprint(engine.publicKey)}</code></label><label>Отпечаток игрока<code class="key-fingerprint" data-no-i18n>${fingerprint}</code></label><button id="verifyKey" class="primary">${changed?'Доверять новому ключу':'Сохранить ключ'}</button>`);$('#verifyKey').onclick=()=>run(async()=>{if(vault.pins[id]!==key)delete vault.replay[id];vault.pins[id]=key;await save();$('#modal').close();await tick();});}
 async function sendTo(id,body,{group='',kind='chat',revision=party?.revision||0}={}){const originalScope=scope,key=await trusted(id);if(scope!==originalScope)throw Error('Аккаунт изменился');const envelope=engine.encrypt(id,key,body,{group,kind,revision});vault.counter=envelope.header.counter;await save();await call('/social/mail',{envelope});return envelope;}
 async function sendChat(chat,body){if(!await init())throw Error('Подключите Spectra Network');const group=chat.startsWith('party:')?chat.slice(6):'',targets=group?(party?.id===group?party.members.filter(m=>m.id!==owner).map(m=>m.id):[]):[chat.slice(3)];if(!targets.length)throw Error('В чате пока нет других участников');const originalScope=scope;await Promise.all(targets.map(trusted));if(originalScope!==scope)throw Error('Аккаунт изменился');const messageId=crypto.randomUUID().replaceAll('-',''),item={id:messageId,from:owner,chat,time:Date.now(),body};for(const id of targets){const envelope=engine.encrypt(id,vault.pins[id],{...body,messageId},{group,kind:'chat',revision:party?.revision||0});vault.counter=envelope.header.counter;vault.outbox.push(envelope);}if(vault.outbox.length>500)throw Error('Очередь отправки переполнена');vault.messages.push(item);vault.messages=vault.messages.slice(-2000);await save();try{await deliver();}catch{toast('Сообщение сохранено в очереди');}if(activeChat===chat)renderChat();}
 async function deliver(){for(const envelope of [...vault.outbox].slice(0,20)){try{await call('/social/mail',{envelope});}catch(e){if(![400,403,404,410].includes(e.status))throw e;toast('Сообщение не отправлено: '+e.message);}vault.outbox=vault.outbox.filter(e=>e.header.id!==envelope.header.id);await save();}}
 async function receive(){const mailbox=await call('/social/mail');const ack=[],completed=new Set(),keyRequests=new Map();let dirty=false;for(const item of [...vault.pending.map(envelope=>({seq:0,envelope})),...(mailbox.items||[])]){const e=item.envelope,h=e?.header;if(!h||!safeId(h.sender)||h.recipient!==owner)continue;const seen=h.sender+':'+h.id;if(vault.seen.includes(seen)){ack.push(item.seq);completed.add(seen);continue;}let pin=vault.pins[h.sender];if(!pin){try{if(!keyRequests.has(h.sender))keyRequests.set(h.sender,trusted(h.sender));pin=await keyRequests.get(h.sender);}catch{}}if(!pin||pin!==e.senderKey){if(item.seq>0){if(!vault.pending.some(p=>p.header.sender+':'+p.header.id===seen)&&vault.pending.length<200){vault.pending.push(e);dirty=true;}if(vault.pending.some(p=>p.header.sender+':'+p.header.id===seen))ack.push(item.seq);}const issue=h.sender+':'+e.senderKey;if(!issues.has(issue)){issues.add(issue);notify('Проверка безопасности',`Ключ ${name(h.sender)} изменился или ещё недоступен. Откройте настройки ключей.`,{type:'verify',id:h.sender});}continue;}
 try{const body=engine.decrypt(e,pin);if(!Number.isSafeInteger(h.counter)||h.counter<1)throw Error('Неверный счётчик');const replay=vault.replay[h.sender]||{max:0,used:[]};if(h.counter<=replay.max-4096||replay.used.includes(h.counter)){ack.push(item.seq);completed.add(seen);continue;}if(h.kind==='signal'&&Math.abs(Date.now()/1000-h.created)>120){ack.push(item.seq);completed.add(seen);continue;}replay.max=Math.max(replay.max,h.counter);replay.used.push(h.counter);replay.used=replay.used.filter(n=>n>replay.max-4096);vault.replay[h.sender]=replay;if(h.kind==='signal'){if(party?.id===h.group&&vault.connected&&party.members.some(m=>m.id===h.sender&&m.online))await signal(h.sender,body);}else{const chat=thread(h.group,h.sender);if(typeof body.text!=='string'&&body.type!=='invite')throw Error('Неверное сообщение');if((body.text||'').length>4000)throw Error('Сообщение слишком длинное');if(!vault.messages.some(m=>m.from===h.sender&&m.body.messageId&&m.body.messageId===body.messageId)){vault.messages.push({id:h.id,from:h.sender,chat,time:h.created*1000,body});notify(name(h.sender),body.type==='invite'?'Приглашение в Minecraft':body.text,{type:'chat',chat,systemMessage:body.type==='invite'},chat);}}
 completed.add(seen);dirty=true;vault.seen.push(seen);vault.seen=vault.seen.slice(-5000);vault.messages=vault.messages.slice(-2000);ack.push(item.seq);
 }catch(e){completed.add(seen);ack.push(item.seq);dirty=true;if(!issues.has(seen)){issues.add(seen);notify('Сообщение не принято',e.message,{type:'verify',id:h.sender});}}
 }if(completed.size){vault.pending=vault.pending.filter(e=>!completed.has(e.header.sender+':'+e.header.id));dirty=true;}const acknowledgements=[...new Set(ack.filter(n=>n>0))];if(dirty||acknowledgements.length){await save();if(acknowledgements.length)await call('/social/ack',{ids:acknowledgements});if(activeChat&&$('#socialChat'))renderChat();}}
 function drop(id){for(const [key,r] of requests)if(r.peer===id){clearTimeout(r.timer);requests.delete(key);r.reject(Error('P2P отключён'));}const peer=peers.get(id);peers.delete(id);worlds.delete(id);clearTimeout(peer?.deadline);peer?.pc.close();if(scope)native('partyTunnel',{operation:'drop',peer:id}).catch(()=>{});}
 function dcSend(id,packet){return new Promise((resolve,reject)=>{const dc=peers.get(id)?.dc;if(dc?.readyState!=='open')return reject(Error('P2P не подключён'));const raw=JSON.stringify(packet);if(raw.length>30000)return reject(Error('Пакет слишком большой'));const deadline=Date.now()+10000;const send=()=>{if(dc.readyState!=='open')return reject(Error('Соединение закрыто'));if(dc.bufferedAmount>256*1024){if(Date.now()>deadline)return reject(Error('Соединение перегружено'));setTimeout(send,20);return;}try{dc.send(raw);resolve();}catch(e){reject(e);}};send();});}
 function channel(id,dc){const peer=peers.get(id);if(!peer)return;peer.dc=dc;dc.bufferedAmountLowThreshold=65536;dc.onopen=()=>{if(peers.get(id)!==peer||peer.status==='failed')return;clearTimeout(peer.deadline);peer.status='connected';publishWorlds(true);refreshPartyView();};dc.onclose=()=>{if(peers.get(id)!==peer||peer.status==='failed')return;peer.status='disconnected';deadline(id,peer,15000);worlds.delete(id);run(()=>native('partyTunnel',{operation:'drop',peer:id}));refreshPartyView();};let incoming=Promise.resolve();dc.onmessage=e=>{incoming=incoming.catch(()=>{}).then(async()=>{if(typeof e.data!=='string'||e.data.length>30000)throw Error('Неверный пакет');const p=JSON.parse(e.data);if(p.type==='request'){serveRequest(id,p,peer);return;}if(p.type==='response'){acceptResponse(id,p);return;}if(p.type==='worlds'){if(!Array.isArray(p.items)||p.items.length>12)throw Error('Неверный список миров');worlds.set(id,p.items.filter(w=>w&&typeof w.id==='string'&&w.id.length<100&&typeof w.version==='string').map(w=>({...w,name:String(w.name||'LAN-мир').slice(0,100),pack:String(w.pack||'').slice(0,100)})));refreshPartyView();}else if(['open','data','close','ack'].includes(p.operation)&&safeId(p.id)){try{await native('partyTunnel',{...p,peer:id});if(p.operation==='data')await dcSend(id,{operation:'ack',id:p.id});}catch{await dcSend(id,{operation:'close',id:p.id});}}}).catch(()=>{});};}
 function peerRequest(peer,kind,data){return new Promise((resolve,reject)=>{if(requests.size>=16)return reject(Error('Слишком много запросов'));const id=crypto.randomUUID().replaceAll('-',''),entry={peer,resolve,reject,parts:[],count:0,size:0,timer:setTimeout(()=>{requests.delete(id);reject(Error('Хост не ответил на запрос сборки'));},60000)};requests.set(id,entry);dcSend(peer,{type:'request',id,kind,...data}).catch(e=>{clearTimeout(entry.timer);requests.delete(id);reject(e);});});}
