 function serveRequest(id,p,peer){if(!safeId(p.id)||!['manifest','read'].includes(p.kind)||typeof p.world!=='string'||p.world.length>100)return;if((peer.requests||0)>=2){dcSend(id,{type:'response',id:p.id,error:'Хост занят передачей'}).catch(()=>{});return;}peer.requests=(peer.requests||0)+1;const originalScope=scope;Promise.resolve().then(async()=>{if(!party?.members.some(m=>m.id===id&&m.online))throw Error('Участник отключён');const result=await native('partyPack',p.kind==='manifest'?{operation:'share',world:p.world}:{operation:'read',world:p.world,hash:String(p.hash||''),offset:p.offset});if(scope!==originalScope||peers.get(id)!==peer)return;const raw=JSON.stringify(result);if(raw.length>1024*1024)throw Error('Сборка слишком большая');const count=Math.max(1,Math.ceil(raw.length/12000));for(let index=0;index<count;index++)await dcSend(id,{type:'response',id:p.id,index,count,part:raw.slice(index*12000,(index+1)*12000)});}).catch(()=>{if(scope===originalScope&&peers.get(id)===peer)dcSend(id,{type:'response',id:p.id,error:'Не удалось передать сборку этого мира. Хост должен разрешить обмен и оставить мир открытым.'}).catch(()=>{});}).finally(()=>peer.requests--);}
 async function downloadWorld(peer,world){const manifest=await peerRequest(peer,'manifest',{world:world.id});if(manifest.version!==world.version||manifest.loader!==world.loader||manifest.loaderVersion!==world.loaderVersion||!Array.isArray(manifest.files)||manifest.files.length>2000)throw Error('Сборка мира изменилась');modal(`${closeButton()}<h2>Сборка LAN-мира</h2><p data-no-i18n>${esc(manifest.name)} · ${esc(manifest.version)} · ${esc(manifest.loader)}</p><p>Выберите файлы. Моды — исполняемый код: устанавливайте сборки только от доверенных людей. Создаётся отдельная сборка.</p><div class="party-pack-files">${manifest.files.map((f,index)=>`<label><input type="checkbox" data-party-file="${index}" checked><span data-no-i18n>${esc(f.kind)}/${esc(f.name)}</span><small>${(Number(f.size)/1024/1024).toFixed(1)} MiB</small></label>`).join('')}</div><p id="partyPackProgress" role="status"></p><button id="partyPackInstall" class="primary">Скачать выбранное по P2P</button>`);let cancelled=false;$('#modal').addEventListener('close',()=>cancelled=true,{once:true});$('#partyPackInstall').onclick=()=>run(async()=>{const button=$('#partyPackInstall');button.disabled=true;const selected=$$('[data-party-file]:checked').map(b=>manifest.files[Number(b.dataset.partyFile)]);let session='';try{session=(await native('partyPack',{operation:'begin',manifest,selected:selected.map(f=>f.kind+'/'+f.name)})).id;let done=0,total=selected.reduce((n,f)=>n+Number(f.size),0);const seen=new Set();for(const file of selected){if(seen.has(file.hash)){done+=file.size;continue;}seen.add(file.hash);for(let offset=0;offset<file.size;offset+=65536){if(cancelled)throw Error('Загрузка отменена');const block=await peerRequest(peer,'read',{world:world.id,hash:file.hash,offset});if(cancelled)throw Error('Загрузка отменена');await native('partyPack',{operation:'write',id:session,hash:file.hash,offset,data:block.data});done+=Math.min(65536,file.size-offset);if($('#partyPackProgress'))$('#partyPackProgress').textContent=file.name+' · '+Math.round(done/Math.max(1,total)*100)+'%';}}if(cancelled)throw Error('Загрузка отменена');const result=await native('partyPack',{operation:'commit',id:session});session='';updateState(result.state);$('#modal').close();toast('Сборка установлена и проверена');await joinWorld(peer,world.id);}finally{if(session)await native('partyPack',{operation:'cancel',id:session});if(button.isConnected)button.disabled=false;}});}
 let iceData=null,iceLoading=null,iceRetryAt=0;
 function validIce(value){if(!Array.isArray(value)||!value.length||value.length>8)throw Error('Неверные ICE-серверы');for(const entry of value){const urls=Array.isArray(entry?.urls)?entry.urls:[entry?.urls];if(!urls.length||urls.length>16||urls.some(url=>typeof url!=='string'||!/^(stun|turn|turns):[^\s]{1,250}$/.test(url)))throw Error('Неверный адрес ICE');if(urls.some(url=>/^turns?:/.test(url))&&(!entry.username||!entry.credential))throw Error('Для TURN необходимы username и credential. Включите автоматический режим или укажите временные данные.');if(String(entry.username||'').length>512||String(entry.credential||'').length>1024)throw Error('Неверные TURN-данные');}return value;}
 async function resolveIce(){if(vault.turnAutomatic===false)return{iceServers:validIce(vault.iceServers?.length?vault.iceServers:[{urls:'stun:stun.cloudflare.com:3478'}]),enabled:false,manual:true};if(iceData?.scope===scope&&iceData.expiresAt>Date.now()/1000+60)return iceData;if(iceLoading)return iceLoading;const captured=scope;const loading=(async()=>{let value;try{value=await call('/social/ice');}catch(e){if(e.status!==404)throw e;value={enabled:false,iceServers:[{urls:'stun:stun.cloudflare.com:3478'}],expiresAt:Date.now()/1000+300,message:'Обновите сервер Spectra для автоматического TURN'};}if(scope!==captured)throw Error('Аккаунт изменился');if(!Number.isFinite(value?.expiresAt)||value.expiresAt<=Date.now()/1000+30)throw Error('Сервер выдал истёкшие TURN-данные');validIce(value.iceServers);return iceData={...value,scope:captured};})();iceLoading=loading;try{return await loading;}finally{if(iceLoading===loading)iceLoading=null;}}
 async function restartPeerIce(id,peer){if(peers.get(id)!==peer||peer.status==='failed')return;if(peer.pc.signalingState!=='stable'){peer.restartPending=true;return;}peer.restartPending=false;peer.announced=false;peer.candidates=[];await peer.pc.setLocalDescription(await peer.pc.createOffer({iceRestart:true}));await sendDescription(id,peer);}
 async function refreshIce(){if(!party||!vault?.connected||vault.turnAutomatic===false||!peers.size||Date.now()<iceRetryAt)return;try{const current=await resolveIce();const version=JSON.stringify(current.iceServers);for(const [id,peer] of peers){if(peer.status==='failed'||peer.iceVersion===version)continue;peer.pc.setConfiguration({iceServers:current.iceServers});peer.iceVersion=version;if(owner<id)await restartPeerIce(id,peer);else await sendTo(id,{restartIce:true,session:peer.session},{group:party.id,kind:'signal'});}}catch(e){iceRetryAt=Date.now()+60000;if(!issues.has('turn-refresh')){issues.add('turn-refresh');notify('Party · TURN',e.message,{type:'party'});}const error=$('#partyError');if(error){error.hidden=false;error.textContent='TURN: '+e.message;}}}
 function connectionFailed(id,peer,message){if(peers.get(id)!==peer||peer.status==='failed')return;clearTimeout(peer.deadline);peer.status='failed';peer.error=message;worlds.delete(id);peer.pc.close();native('partyTunnel',{operation:'drop',peer:id}).catch(()=>{});refreshPartyView();}
