 async function inviteGame(chat){const presence=(await api('friendsPresence'));if(!presence?.playing)throw Error('Сначала запустите Minecraft');if(presence.targetKind==='lan'||presence.gameState==='world'){if(chat.startsWith('dm:')){if(!party){if(!await ask('Создать группу с другом?','Для подключения к LAN-миру потребуется Party. Участники могут узнать IP друг друга.','Создать'))return;await operation('create',{consent:true,name:'Party · '+state.profile.name});}await operation('invite',{id:chat.slice(3)});toast('Приглашение в группу отправлено');return;}await sendChat(chat,{type:'invite',targetKind:'lan',text:'Приглашает в LAN-мир',party:party?.id});return;}if(presence.targetKind!=='servers'||!presence.target)throw Error('Откройте мир для сети или зайдите на сервер');await sendChat(chat,{type:'invite',targetKind:'servers',target:presence.target,version:presence.version,loader:presence.loader,loaderVersion:presence.loaderVersion,text:'Приглашает на сервер '+presence.target});toast('Приглашение отправлено');}
 async function openGameInvite(message){const b=message.body;if(b.targetKind==='lan'){view='worlds';await showParty();return;}if(b.targetKind!=='servers'||typeof b.target!=='string'||b.target.length>255||! /^[a-z0-9.\-\[\]:_]+$/i.test(b.target))throw Error('Неверный адрес приглашения');modal(`${closeButton()}<h2>Приглашение в Minecraft</h2><p data-no-i18n>${esc(name(message.from))} · ${esc(b.target)}</p><p>${esc(b.version)} · ${esc(b.loader)}</p><select id="inviteGameInstance">${(state.instances||[]).filter(i=>i.version===b.version&&i.loader===b.loader&&(i.loaderVersion||'')===(b.loaderVersion||'')).map(i=>`<option value="${i.id}" data-no-i18n>${esc(i.name)}</option>`).join('')}${b.loader==='vanilla'?'<option value="vanilla">Minecraft Vanilla</option>':''}</select><button id="acceptGameInvite" class="primary">Подключиться</button>`);$('#acceptGameInvite').onclick=()=>run(async()=>{const id=$('#inviteGameInstance').value;if(!id)throw Error('Установите совместимую сборку');updateState(await api('launchInvitation',{instanceId:id,version:b.version,target:b.target}));$('#modal').close();});}
 async function navigateAction(action){if(action.scope&&action.scope!==scope)throw Error('Это уведомление другого аккаунта');if(action.type==='party')await showParty();else if(action.type==='chat')await openChat(action.chat);else if(action.type==='verify')await verify(action.id);else if(action.type==='friend'){await api('expand');await navigate('profile');const friend=friends.find(f=>f.id===action.id);if(friend?.minecraftName)renderProfile(await api('player',{name:friend.minecraftName}));}}
 function bindFriends(known=[]){if(known.length)friends=known.filter(f=>f.relation==='friend');const tabs=$('#friendsPanel .friends-tabs');if(!tabs)return;const button=document.createElement('button');button.id='partyTab';button.textContent='Группа';button.hidden=!party&&!invitations.length;button.onclick=()=>run(showParty);tabs.append(button);const createButton=document.createElement('button');createButton.textContent='Создать группу';createButton.id='createParty';createButton.onclick=()=>run(create);$('#friendsPanel .friends-actions')?.append(createButton);for(const row of $$('#friendsPanel .friend-row')){const id=row.querySelector('[data-friend-profile]')?.dataset.friendProfile;const friend=friends.find(f=>f.id===id);if(!friend)continue;const buttons=row.querySelector('.friend-details>div');if(!buttons)continue;const chat=document.createElement('button');chat.textContent='Чат';chat.onclick=()=>run(()=>openChat('dm:'+id));buttons.prepend(chat);const invite=document.createElement('button');invite.textContent='Пригласить';invite.onclick=()=>run(()=>inviteGame('dm:'+id));buttons.append(invite);if(party){const group=document.createElement('button');group.textContent='В группу';group.onclick=()=>run(async()=>{await operation('invite',{id});toast('Приглашение отправлено');});buttons.append(group);}}}
 function accountState(){if(owner&&(owner!==state.networkAccount?.id||vault?.endpoint!==state.friendsEndpoint)){SpectraShell.clearSocialNotices?.();for(const [id,r] of requests){clearTimeout(r.timer);r.reject(Error('Аккаунт изменился'));}requests.clear();for(const id of [...peers.keys()])drop(id);worlds.clear();engine?.destroy();engine=null;iceData=null;iceLoading=null;iceRetryAt=0;scope='';owner='';vault=null;party=null;ready=false;api('partyReset').catch(()=>{});}}
 function message(m){if(m.type==='socialTick')tick();if(m.type==='socialNavigate')run(()=>navigateAction(m.action));if(m.type==='partyTcp'){if(!scope)return;const id=m.peer;if(!party?.members.some(member=>member.id===id&&member.online)||!vault?.connected){run(()=>native('partyTunnel',{operation:'close',peer:id,id:m.id}));return;}dcSend(id,m).catch(()=>run(()=>native('partyTunnel',{operation:'close',peer:id,id:m.id})));}}
 document.addEventListener('visibilitychange',()=>{if(!document.hidden)tick();});
 return{tick,message,accountState,bindFriends,showParty,create,openChat,navigateAction,verify,inviteGame};
